import React, { useState } from 'react';
import { COMPANY_DATA, COLOR_CONFIG } from '../constants';

interface SidebarProps {
  isOpen: boolean;
  onNavigate: (deptId: number | null, sectionId: string | null) => void;
  onClose: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ isOpen, onNavigate, onClose }) => {
  const [expandedDeptIds, setExpandedDeptIds] = useState<number[]>([]);

  const toggleDept = (id: number) => {
    setExpandedDeptIds(prev => 
      prev.includes(id) ? prev.filter(did => did !== id) : [...prev, id]
    );
  };

  const handleHomeClick = () => {
    onNavigate(null, null);
    if (window.innerWidth < 1024) onClose();
  };

  const handleSectionClick = (deptId: number, sectionId: string) => {
    onNavigate(deptId, sectionId);
    if (window.innerWidth < 1024) onClose();
  };

  return (
    <>
      {/* Overlay for mobile */}
      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden"
          onClick={onClose}
        />
      )}

      <aside 
        className={`
          fixed top-0 left-0 h-full w-72 bg-slate-900 text-white z-50 
          transform transition-transform duration-300 ease-in-out
          ${isOpen ? 'translate-x-0' : '-translate-x-full'}
          lg:translate-x-0 lg:static overflow-y-auto scrollbar-hide
        `}
      >
        {/* Logo Section */}
        <div className="p-6 border-b border-slate-700">
          <div className="flex items-center gap-3">
            <img 
              src="https://media.licdn.com/dms/image/v2/C4D0BAQGxApknM8O3Vg/company-logo_200_200/company-logo_200_200/0/1630525227090?e=2147483647&v=beta&t=Qk8mPjKVPMDQ5qxJqJQxQxPqPqPqPqPqPqPqPqPqPqQ" 
              alt="Agile Logo" 
              className="w-12 h-12 rounded-lg bg-white p-1 object-contain"
              onError={(e) => {
                (e.target as HTMLImageElement).src = 'https://ui-avatars.com/api/?name=Agile&background=0066CC&color=fff&size=48';
              }}
            />
            <div>
              <h1 className="text-xl font-bold text-white">Agile</h1>
              <p className="text-xs text-slate-400">FTTH Database System</p>
            </div>
          </div>
        </div>

        {/* Navigation */}
        <nav className="p-4">
          <div className="mb-4">
            <button 
              onClick={handleHomeClick}
              className="w-full flex items-center gap-3 px-4 py-3 rounded-lg bg-blue-600 text-white hover:bg-blue-700 transition-colors shadow-lg shadow-blue-900/20"
            >
              <i className="fas fa-home"></i>
              <span>Dashboard Home</span>
            </button>
          </div>

          <p className="text-xs text-slate-500 uppercase tracking-wider px-4 mb-2 font-semibold">Departments</p>

          <div className="space-y-1">
            {COMPANY_DATA.departments.map((dept) => {
              const isExpanded = expandedDeptIds.includes(dept.id);
              const iconClass = COLOR_CONFIG[dept.color].icon;

              return (
                <div key={dept.id}>
                  <button 
                    className={`
                      w-full flex items-center justify-between px-4 py-3 rounded-lg 
                      hover:bg-slate-800 transition-all duration-200 text-left group
                      ${isExpanded ? 'bg-slate-800' : ''}
                    `}
                    onClick={() => toggleDept(dept.id)}
                  >
                    <div className="flex items-center gap-3">
                      <div className={`w-6 flex justify-center ${iconClass} group-hover:scale-110 transition-transform`}>
                        <i className={`fas fa-${dept.icon}`}></i>
                      </div>
                      <span className="text-sm font-medium text-slate-200 group-hover:text-white">{dept.name}</span>
                    </div>
                    <i className={`fas fa-chevron-down text-xs text-slate-500 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`}></i>
                  </button>

                  <div 
                    className={`
                      overflow-hidden transition-all duration-300 ease-in-out
                      ${isExpanded ? 'max-h-[1000px] opacity-100' : 'max-h-0 opacity-0'}
                    `}
                  >
                    <div className="pl-4 pr-2 py-1 space-y-1">
                      {dept.sections.map((section) => (
                        <button
                          key={section.id}
                          onClick={() => handleSectionClick(dept.id, section.id)}
                          className="w-full flex items-center gap-2 py-2 px-3 text-sm text-slate-400 hover:text-white hover:bg-slate-700/50 rounded-lg transition-colors text-left border-l-2 border-transparent hover:border-slate-500 ml-2"
                        >
                          <i className="fas fa-angle-right text-xs opacity-50"></i>
                          {section.name}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>

          {/* Shortcuts */}
          <div className="mt-8 pt-4 border-t border-slate-700">
            <p className="text-xs text-slate-500 uppercase tracking-wider px-4 mb-3 font-semibold">Shortcuts</p>
            <div className="px-1">
              <a 
                href="https://baserow.io/workspace/160461" 
                target="_blank" 
                rel="noreferrer"
                className="flex items-center gap-3 px-4 py-3 rounded-lg bg-gradient-to-r from-emerald-600 to-emerald-700 text-white hover:from-emerald-500 hover:to-emerald-600 transition-all shadow-lg hover:shadow-emerald-500/25 group"
              >
                <div className="w-8 h-8 bg-white/20 rounded-lg flex items-center justify-center group-hover:scale-110 transition-transform">
                  <i className="fas fa-table"></i>
                </div>
                <div>
                  <span className="font-medium text-sm block">Baserow Database</span>
                  <span className="text-[10px] text-emerald-200 uppercase tracking-wide">External Workspace</span>
                </div>
                <i className="fas fa-external-link-alt text-xs ml-auto opacity-75"></i>
              </a>
            </div>
          </div>
        </nav>

        {/* Footer */}
        <div className="p-4 border-t border-slate-700 bg-slate-900 mt-auto sticky bottom-0">
          <div className="flex items-center gap-2 text-slate-400 text-sm justify-center">
            <i className="fas fa-network-wired"></i>
            <span>FTTH Management v2.0</span>
          </div>
        </div>
      </aside>
    </>
  );
};

import React from 'react';
import { Department, Section } from '../types';
import { COLOR_CONFIG } from '../constants';

interface DepartmentCardProps {
  dept: Department;
  onSelectSection: (deptId: number, sectionId: string) => void;
}

export const DepartmentCard: React.FC<DepartmentCardProps> = ({ dept, onSelectSection }) => {
  const colors = COLOR_CONFIG[dept.color];
  const activeLinks = dept.sections.reduce((acc, section) => 
    acc + section.labels.filter(l => l.hyperlinked).length, 0);

  return (
    <div className="bg-white rounded-2xl shadow-lg overflow-hidden border border-gray-100 hover:shadow-2xl transition-all duration-300 hover:-translate-y-1 flex flex-col h-full">
      <div className={`${colors.bg} p-5 text-white`}>
        <div className="flex items-center gap-4">
          <div className="w-14 h-14 bg-white/20 rounded-xl flex items-center justify-center shadow-inner backdrop-blur-sm">
            <i className={`fas fa-${dept.icon} text-2xl`}></i>
          </div>
          <div>
            <h3 className="text-xl font-bold leading-tight">{dept.name}</h3>
            <p className="text-sm opacity-90 mt-1 font-light">
              {dept.sections.length} Sections • {activeLinks} Active Links
            </p>
          </div>
        </div>
      </div>

      <div className="p-6 flex-1 flex flex-col">
        {dept.description && (
          <p className="text-sm text-gray-500 mb-5 bg-gray-50 p-3 rounded-lg border border-gray-100">
            <i className="fas fa-info-circle mr-2 text-gray-400"></i>
            {dept.description}
          </p>
        )}

        <div className="space-y-3 mt-auto">
          {dept.sections.map((section: Section) => (
            <button 
              key={section.id}
              onClick={() => onSelectSection(dept.id, section.id)}
              className={`
                w-full text-left p-3 rounded-xl ${colors.light} 
                hover:shadow-md transition-all duration-200 group border border-transparent ${colors.hoverBorder}
              `}
            >
              <div className="flex items-center justify-between mb-2">
                <div className="flex items-center gap-2">
                  <i className={`fas fa-folder ${colors.text} text-sm`}></i>
                  <span className="font-semibold text-gray-700 text-sm">{section.name}</span>
                </div>
                <i className={`fas fa-arrow-right ${colors.text} text-xs opacity-0 -translate-x-2 group-hover:opacity-100 group-hover:translate-x-0 transition-all`}></i>
              </div>

              <div className="flex gap-2 flex-wrap">
                {section.labels.filter(l => l.hyperlinked).slice(0, 3).map((l, idx) => (
                  <span key={idx} className="text-[10px] px-2 py-0.5 bg-white rounded-full text-gray-500 border border-gray-100 shadow-sm">
                    {l.name.split(' ')[0]}
                  </span>
                ))}
                {section.labels.filter(l => l.hyperlinked).length > 3 && (
                   <span className="text-[10px] px-2 py-0.5 bg-white rounded-full text-gray-400">
                    +{section.labels.filter(l => l.hyperlinked).length - 3}
                  </span>
                )}
              </div>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

import React, { useEffect } from 'react';
import { Department, Section } from '../types';
import { COLOR_CONFIG, LABEL_ICONS } from '../constants';

interface SectionDetailProps {
  dept: Department;
  section: Section;
  onBack: () => void;
}

export const SectionDetail: React.FC<SectionDetailProps> = ({ dept, section, onBack }) => {
  const colors = COLOR_CONFIG[dept.color];

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, []);

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
      <button 
        onClick={onBack}
        className="flex items-center gap-2 text-blue-600 hover:text-blue-800 mb-8 px-4 py-2 rounded-lg hover:bg-blue-50 transition-colors w-fit"
      >
        <i className="fas fa-arrow-left"></i>
        <span className="font-medium">Back to Departments</span>
      </button>

      <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-gray-100 mb-8">
        <div className="p-8 md:p-10 border-b border-gray-100 relative overflow-hidden">
          {/* Decorative background element */}
          <div className={`absolute -right-10 -top-10 w-64 h-64 ${colors.bg} opacity-5 rounded-full blur-3xl`}></div>

          <div className="relative z-10 flex flex-col md:flex-row md:items-center gap-6">
            <div className={`w-20 h-20 ${colors.bg} rounded-2xl flex items-center justify-center text-white shadow-lg ${colors.shadow}`}>
              <i className={`fas fa-${dept.icon} text-3xl`}></i>
            </div>
            <div>
              <div className={`inline-flex items-center gap-2 px-3 py-1 rounded-full ${colors.light} ${colors.text} text-xs font-semibold mb-2`}>
                 <span className={`w-1.5 h-1.5 rounded-full ${colors.bg}`}></span>
                 {dept.name}
              </div>
              <h2 className="text-3xl md:text-4xl font-bold text-gray-900 tracking-tight">{section.name}</h2>
              <p className="text-gray-500 mt-2">Manage databases, access dashboards, and view records for this section.</p>
            </div>
          </div>
        </div>

        <div className="p-8 md:p-10 bg-gray-50/50">
           <h3 className="text-sm font-semibold text-gray-400 uppercase tracking-wider mb-6">Available Resources</h3>

           <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-5">
            {section.labels.map((label, idx) => {
              const icon = LABEL_ICONS[label.name] || 'fa-link';
              const isActive = label.hyperlinked;

              if (isActive && label.url) {
                return (
                  <a 
                    key={idx}
                    href={label.url} 
                    target="_blank" 
                    rel="noreferrer"
                    className="group relative flex flex-col p-6 rounded-2xl bg-white border border-gray-100 shadow-sm hover:shadow-xl hover:shadow-blue-500/10 hover:-translate-y-1 transition-all duration-300"
                  >
                    <div className="absolute top-0 right-0 p-4 opacity-0 group-hover:opacity-100 transition-opacity">
                      <i className="fas fa-external-link-alt text-blue-400 text-sm"></i>
                    </div>

                    <div className="flex items-center gap-4 mb-4">
                      <div className="w-12 h-12 bg-blue-50 rounded-xl flex items-center justify-center text-blue-600 group-hover:bg-blue-600 group-hover:text-white transition-colors duration-300">
                        <i className={`fas ${icon} text-lg`}></i>
                      </div>
                      <div className="flex flex-col">
                         <span className="text-xs text-green-600 font-medium bg-green-50 px-2 py-0.5 rounded-full w-fit mb-1 flex items-center gap-1">
                            <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse-custom"></span>
                            Active
                         </span>
                         <h4 className="font-bold text-gray-800 group-hover:text-blue-700 transition-colors">{label.name}</h4>
                      </div>
                    </div>

                    <div className="mt-auto pt-4 border-t border-gray-50">
                       <p className="text-xs text-gray-400 truncate font-mono">
                         {label.url.replace(/^https?:\/\//, '')}
                       </p>
                    </div>
                  </a>
                );
              } else {
                return (
                  <div key={idx} className="flex flex-col p-6 rounded-2xl bg-gray-50 border-2 border-dashed border-gray-200 opacity-75 cursor-not-allowed select-none">
                    <div className="flex items-center gap-4 mb-4">
                      <div className="w-12 h-12 bg-gray-200 rounded-xl flex items-center justify-center text-gray-400">
                        <i className={`fas ${icon} text-lg`}></i>
                      </div>
                      <div className="flex flex-col">
                        <span className="text-xs text-gray-400 font-medium bg-gray-200/50 px-2 py-0.5 rounded-full w-fit mb-1">
                            Not Available
                         </span>
                         <h4 className="font-bold text-gray-400">{label.name}</h4>
                      </div>
                    </div>
                    <div className="mt-auto pt-4 border-t border-gray-200/50">
                       <p className="text-xs text-gray-400">Resource currently offline</p>
                    </div>
                  </div>
                );
              }
            })}
          </div>
        </div>
      </div>
    </div>
  );
};

