const App: React.FC = () => {
  // Authentication State
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  // App State
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [activeSection, setActiveSection] = useState<ActiveSectionState | null>(null);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (username.trim() === 'baker' && password === '0000') {
      setIsAuthenticated(true);
      setError('');
    } else {
      setError('Invalid username or password');
    }
  };

  const handleNavigate = (deptId: number | null, sectionId: string | null) => {
    if (deptId !== null && sectionId !== null) {
      setActiveSection({ deptId, sectionId });
    } else {
      setActiveSection(null);
    }
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const currentDept = activeSection 
    ? COMPANY_DATA.departments.find(d => d.id === activeSection.deptId) 
    : null;

  const currentSection = currentDept && activeSection
    ? currentDept.sections.find(s => s.id === activeSection.sectionId)
    : null;

  // Render Login Screen if not authenticated
  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4 relative overflow-hidden">
        {/* Background Patterns */}
        <div className="absolute inset-0 fiber-pattern opacity-10"></div>
        <div className="absolute top-0 left-0 w-full h-full bg-[url('https://images.unsplash.com/photo-1558494949-ef010cbdcc31?w=1920')] bg-cover bg-center opacity-10 mix-blend-overlay"></div>

        <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md p-8 relative z-10 animate-in fade-in zoom-in duration-500">
          <div className="text-center mb-8">
            <img 
              src="https://media.licdn.com/dms/image/v2/C4D0BAQGxApknM8O3Vg/company-logo_200_200/company-logo_200_200/0/1630525227090" 
              alt="Agile Logo" 
              className="w-20 h-20 mx-auto rounded-2xl bg-slate-50 p-2 object-contain shadow-lg mb-4"
              onError={(e) => {
                (e.target as HTMLImageElement).src = 'https://ui-avatars.com/api/?name=Agile&background=0066CC&color=fff&size=80';
              }}
            />
            <h1 className="text-2xl font-bold text-gray-800">Welcome Back</h1>
            <p className="text-gray-500 text-sm mt-1">Sign in to FTTH Database System</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-6">
            {error && (
              <div className="p-3 rounded-lg bg-red-50 text-red-600 text-sm flex items-center gap-2 border border-red-100">
                <i className="fas fa-exclamation-circle"></i>
                {error}
              </div>
            )}

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Username</label>
              <div className="relative">
                <i className="fas fa-user absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
                <input
                  type="text"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 rounded-xl border border-gray-200 focus:border-blue-500 focus:ring-2 focus:ring-blue-100 outline-none transition-all"
                  placeholder="Enter username"
                  required
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Password</label>
              <div className="relative">
                <i className="fas fa-lock absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
                <input
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 rounded-xl border border-gray-200 focus:border-blue-500 focus:ring-2 focus:ring-blue-100 outline-none transition-all"
                  placeholder="Enter password"
                  required
                />
              </div>
            </div>

            <button
              type="submit"
              className="w-full bg-blue-600 text-white py-3 rounded-xl font-semibold hover:bg-blue-700 transition-colors shadow-lg shadow-blue-500/30 flex items-center justify-center gap-2"
            >
              <span>Sign In</span>
              <i className="fas fa-arrow-right text-sm"></i>
            </button>
          </form>

          <div className="mt-8 pt-6 border-t border-gray-100 text-center">
             <p className="text-xs text-gray-400">Agile Solutions • FTTH Management v2.0</p>
          </div>
        </div>
      </div>
    );
  }

  // Render Main App
  return (
    <div className="flex min-h-screen bg-gray-50">
      {/* Sidebar */}
      <Sidebar 
        isOpen={sidebarOpen} 
        onNavigate={handleNavigate} 
        onClose={() => setSidebarOpen(false)} 
      />

      {/* Mobile Menu Toggle */}
      <button 
        onClick={() => setSidebarOpen(!sidebarOpen)}
        className="lg:hidden fixed top-4 left-4 z-40 bg-blue-600 text-white p-3 rounded-lg shadow-xl hover:bg-blue-700 transition-colors"
        aria-label="Toggle Menu"
      >
        <i className="fas fa-bars text-xl"></i>
      </button>

      {/* Main Content */}
      <main className="flex-1 lg:ml-72 min-h-screen w-full transition-all duration-300">
        <div className="max-w-7xl mx-auto">

          {/* Conditional Rendering */}
          {!activeSection ? (
            // Dashboard Home View
            <>
              <div className="px-6 pt-6">
                <Hero />
              </div>

              <div className="px-6 pb-20">
                <div className="max-w-6xl mx-auto">
                   <Stats />

                  <div className="flex items-end justify-between mb-8 border-b border-gray-200 pb-4">
                    <div>
                      <h2 className="text-3xl font-bold text-gray-800">Departments</h2>
                      <p className="text-gray-500 mt-1">Access all department databases and dashboards</p>
                    </div>
                  </div>

                  <div className="grid md:grid-cols-2 gap-8 mb-16 fiber-pattern rounded-3xl p-4 md:p-8 border border-slate-100 bg-white/50 backdrop-blur-sm">
                    {COMPANY_DATA.departments.map(dept => (
                      <DepartmentCard 
                        key={dept.id} 
                        dept={dept} 
                        onSelectSection={(deptId, sectionId) => handleNavigate(deptId, sectionId)}
                      />
                    ))}
                  </div>
                </div>
              </div>

              {/* FTTH Info Footer Section */}
              <section className="py-16 px-6 bg-gradient-to-r from-slate-900 to-slate-800 text-white">
                <div className="max-w-6xl mx-auto">
                  <h2 className="text-2xl font-bold mb-10 text-center relative">
                    <span className="relative z-10">FTTH Infrastructure Overview</span>
                    <span className="absolute bottom-0 left-1/2 -translate-x-1/2 w-20 h-1 bg-blue-500 rounded-full mt-2"></span>
                  </h2>
                  <div className="grid md:grid-cols-4 gap-6">
                    {[
                      { icon: 'network-wired', color: 'text-blue-400', title: 'Fiber Deployment', desc: 'Complete fiber network infrastructure management' },
                      { icon: 'wifi', color: 'text-orange-400', title: 'Wireless Solutions', desc: 'Enterprise wireless connectivity services' },
                      { icon: 'tools', color: 'text-green-400', title: 'Installation & Maint.', desc: 'User installation and maintenance tracking' },
                      { icon: 'hard-hat', color: 'text-yellow-400', title: 'Civil Works', desc: 'Drilling, OSP, and QC operations' }
                    ].map((item, idx) => (
                      <div key={idx} className="text-center p-6 bg-white/5 rounded-2xl backdrop-blur-md border border-white/5 hover:bg-white/10 transition-colors">
                        <i className={`fas fa-${item.icon} text-4xl ${item.color} mb-4`}></i>
                        <h3 className="font-semibold mb-2 text-lg">{item.title}</h3>
                        <p className="text-sm text-slate-400">{item.desc}</p>
                      </div>
                    ))}
                  </div>
                </div>
              </section>
            </>
          ) : (
            // Section Detail View
            <div className="p-6 pt-24 lg:pt-10 min-h-screen">
              {currentDept && currentSection && (
                <div className="max-w-6xl mx-auto">
                  <SectionDetail 
                    dept={currentDept} 
                    section={currentSection} 
                    onBack={() => handleNavigate(null, null)} 
                  />
                </div>
              )}
            </div>
          )}

          {/* Site Footer */}
          <footer className="bg-slate-900 text-white py-8 px-6 border-t border-slate-800">
            <div className="max-w-6xl mx-auto">
              <div className="flex flex-col md:flex-row justify-between items-center gap-6">
                <div className="flex items-center gap-4">
                  <img 
                    src="https://media.licdn.com/dms/image/v2/C4D0BAQGxApknM8O3Vg/company-logo_200_200/company-logo_200_200/0/1630525227090" 
                    alt="Agile Logo" 
                    className="w-10 h-10 rounded-lg bg-white p-1 object-contain"
                    onError={(e) => {
                      (e.target as HTMLImageElement).src = 'https://ui-avatars.com/api/?name=Agile&background=fff&color=0066CC&size=40';
                    }}
                  />
                  <div>
                    <div className="font-bold text-lg">Agile Solutions</div>
                    <div className="text-xs text-slate-400">FTTH Database Management System</div>
                  </div>
                </div>
                <div className="text-slate-400 text-sm">
                  © {new Date().getFullYear()} Agile Solutions. All rights reserved.
                </div>
              </div>
            </div>
          </footer>

        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { COMPANY_DATA, COLOR_CONFIG } from '../constants';

interface SidebarProps {
  isOpen: boolean;
  onNavigate: (deptId: number | null, sectionId: string | null) => void;
  onClose: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ isOpen, onNavigate, onClose }) => {
  const [expandedDeptIds, setExpandedDeptIds] = useState<number[]>([]);

  const toggleDept = (id: number) => {
    setExpandedDeptIds(prev => 
      prev.includes(id) ? prev.filter(did => did !== id) : [...prev, id]
    );
  };

  const handleHomeClick = () => {
    onNavigate(null, null);
    if (window.innerWidth < 1024) onClose();
  };

  const handleSectionClick = (deptId: number, sectionId: string) => {
    onNavigate(deptId, sectionId);
    if (window.innerWidth < 1024) onClose();
  };

  return (
    <>
      {/* Overlay for mobile */}
      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden"
          onClick={onClose}
        />
      )}

      <aside 
        className={`
          fixed top-0 left-0 h-full w-72 bg-slate-900 text-white z-50 
          transform transition-transform duration-300 ease-in-out
          ${isOpen ? 'translate-x-0' : '-translate-x-full'}
          lg:translate-x-0 lg:static overflow-y-auto scrollbar-hide
        `}
      >
        {/* Logo Section */}
        <div className="p-6 border-b border-slate-700">
          <div className="flex items-center gap-3">
            <img 
              src="https://media.licdn.com/dms/image/v2/C4D0BAQGxApknM8O3Vg/company-logo_200_200/company-logo_200_200/0/1630525227090?e=2147483647&v=beta&t=Qk8mPjKVPMDQ5qxJqJQxQxPqPqPqPqPqPqPqPqPqPqQ" 
              alt="Agile Logo" 
              className="w-12 h-12 rounded-lg bg-white p-1 object-contain"
              onError={(e) => {
                (e.target as HTMLImageElement).src = 'https://ui-avatars.com/api/?name=Agile&background=0066CC&color=fff&size=48';
              }}
            />
            <div>
              <h1 className="text-xl font-bold text-white">Agile</h1>
              <p className="text-xs text-slate-400">FTTH Database System</p>
            </div>
          </div>
        </div>

        {/* Navigation */}
        <nav className="p-4">
          <div className="mb-4">
            <button 
              onClick={handleHomeClick}
              className="w-full flex items-center gap-3 px-4 py-3 rounded-lg bg-blue-600 text-white hover:bg-blue-700 transition-colors shadow-lg shadow-blue-900/20"
            >
              <i className="fas fa-home"></i>
              <span>Dashboard Home</span>
            </button>
          </div>

          <p className="text-xs text-slate-500 uppercase tracking-wider px-4 mb-2 font-semibold">Departments</p>

          <div className="space-y-1">
            {COMPANY_DATA.departments.map((dept) => {
              const isExpanded = expandedDeptIds.includes(dept.id);
              const iconClass = COLOR_CONFIG[dept.color].icon;

              return (
                <div key={dept.id}>
                  <button 
                    className={`
                      w-full flex items-center justify-between px-4 py-3 rounded-lg 
                      hover:bg-slate-800 transition-all duration-200 text-left group
                      ${isExpanded ? 'bg-slate-800' : ''}
                    `}
                    onClick={() => toggleDept(dept.id)}
                  >
                    <div className="flex items-center gap-3">
                      <div className={`w-6 flex justify-center ${iconClass} group-hover:scale-110 transition-transform`}>
                        <i className={`fas fa-${dept.icon}`}></i>
                      </div>
                      <span className="text-sm font-medium text-slate-200 group-hover:text-white">{dept.name}</span>
                    </div>
                    <i className={`fas fa-chevron-down text-xs text-slate-500 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`}></i>
                  </button>

                  <div 
                    className={`
                      overflow-hidden transition-all duration-300 ease-in-out
                      ${isExpanded ? 'max-h-[1000px] opacity-100' : 'max-h-0 opacity-0'}
                    `}
                  >
                    <div className="pl-4 pr-2 py-1 space-y-1">
                      {dept.sections.map((section) => (
                        <button
                          key={section.id}
                          onClick={() => handleSectionClick(dept.id, section.id)}
                          className="w-full flex items-center gap-2 py-2 px-3 text-sm text-slate-400 hover:text-white hover:bg-slate-700/50 rounded-lg transition-colors text-left border-l-2 border-transparent hover:border-slate-500 ml-2"
                        >
                          <i className="fas fa-angle-right text-xs opacity-50"></i>
                          {section.name}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>

          {/* Shortcuts */}
          <div className="mt-8 pt-4 border-t border-slate-700">
            <p className="text-xs text-slate-500 uppercase tracking-wider px-4 mb-3 font-semibold">Shortcuts</p>
            <div className="px-1 space-y-3">
              <a 
                href="https://baserow.io/workspace/160461" 
                target="_blank" 
                rel="noreferrer"
                className="flex items-center gap-3 px-4 py-3 rounded-lg bg-gradient-to-r from-emerald-600 to-emerald-700 text-white hover:from-emerald-500 hover:to-emerald-600 transition-all shadow-lg hover:shadow-emerald-500/25 group"
              >
                <div className="w-8 h-8 bg-white/20 rounded-lg flex items-center justify-center group-hover:scale-110 transition-transform">
                  <i className="fas fa-table"></i>
                </div>
                <div>
                  <span className="font-medium text-sm block">Baserow Database</span>
                  <span className="text-[10px] text-emerald-200 uppercase tracking-wide">External Workspace</span>
                </div>
                <i className="fas fa-external-link-alt text-xs ml-auto opacity-75"></i>
              </a>

              <a 
                href="https://aistudio.google.com/prompts/1vEoCqtWkdI6NjubInrCdAc6om--DSp9q" 
                target="_blank" 
                rel="noreferrer"
                className="flex items-center gap-3 px-4 py-3 rounded-lg bg-gradient-to-r from-indigo-600 to-indigo-700 text-white hover:from-indigo-500 hover:to-indigo-600 transition-all shadow-lg hover:shadow-indigo-500/25 group"
              >
                <div className="w-8 h-8 bg-white/20 rounded-lg flex items-center justify-center group-hover:scale-110 transition-transform">
                  <i className="fas fa-paper-plane"></i>
                </div>
                <div>
                  <span className="font-medium text-sm block">Document Sender</span>
                  <span className="text-[10px] text-indigo-200 uppercase tracking-wide">Form for Ankidoo</span>
                </div>
                <i className="fas fa-external-link-alt text-xs ml-auto opacity-75"></i>
              </a>
            </div>
          </div>
        </nav>

        {/* Footer */}
        <div className="p-4 border-t border-slate-700 bg-slate-900 mt-auto sticky bottom-0">
          <div className="flex items-center gap-2 text-slate-400 text-sm justify-center">
            <i className="fas fa-network-wired"></i>
            <span>FTTH Management v2.0</span>
          </div>
        </div>
      </aside>
    </>
  );
};

