                    <div className="pl-4 pr-2 py-1 space-y-1">
                      {dept.sections.map((section) => {
                        if (section.subSections) {
                           const isSubExpanded = expandedSectionIds.includes(section.id);
                           return (
                             <div key={section.id}>
                               <button
                                 onClick={(e) => toggleSection(e, section.id)}
                                 className="w-full flex items-center justify-between py-2 px-3 text-sm text-slate-400 hover:text-white hover:bg-slate-700/50 rounded-lg transition-colors text-left border-l-2 border-transparent hover:border-slate-500 ml-2"
